package com.hmdp.ai.domain.artifact;public final class ArtifactRecord {private final String id,tenantId,workspaceId,runId,name,contentType,objectKey,createdBy,status;private final long sizeBytes;public ArtifactRecord(String id,String tenantId,String workspaceId,String runId,String name,String contentType,String objectKey,long sizeBytes,String createdBy,String status){this.id=id;this.tenantId=tenantId;this.workspaceId=workspaceId;this.runId=runId;this.name=name;this.contentType=contentType;this.objectKey=objectKey;this.sizeBytes=sizeBytes;this.createdBy=createdBy;this.status=status;}public String getId(){return id;}public String getTenantId(){return tenantId;}public String getWorkspaceId(){return workspaceId;}public String getRunId(){return runId;}public String getName(){return name;}public String getContentType(){return contentType;}public String getObjectKey(){return objectKey;}public long getSizeBytes(){return sizeBytes;}public String getCreatedBy(){return createdBy;}public String getStatus(){return status;}}
